import * as p from '@clack/prompts';
import arg from 'arg';
import pc from 'picocolors';
import { bootstrapCommand } from './commands/bootstrap.js';
import { buildLambdaZipCommand } from './commands/build-lambda-zip.js';
import { debugCommand } from './commands/debug.js';
import { deployCommand } from './commands/deploy.js';
import { dumpTokensCommand } from './commands/dump-tokens.js';
import { envCommand } from './commands/env.js';
import { initCommand } from './commands/init.js';
import { listTokensCommand } from './commands/list-tokens.js';
import { loginCommand } from './commands/login.js';
import { logoutCommand } from './commands/logout.js';
import { setupAgentCommand } from './commands/setup-agent.js';
import { upgradeCommand } from './commands/upgrade.js';
import { uploadSchemaCommand } from './commands/upload-schema.js';
import { setInfraEnvironment } from './constants.js';
import { helpMessage } from './utils/messages.js';
export const cliArgSpec = {
    '--adapter': String,
    '--all': Boolean,
    '--callback-url': String,
    '--complete': String,
    '--debug': Boolean,
    '--description': String,
    '--dry-run': Boolean,
    '--env': String,
    '--force': Boolean,
    '--global': Boolean,
    '--headless': Boolean,
    '--help': Boolean,
    '--id': String,
    '--infra-env': String,
    '--json': Boolean,
    '--name': String,
    '--no-agent': Boolean,
    '--output': String,
    '--payload-version': String,
    '--project': Boolean,
    '--region': String,
    '--skip-auth': Boolean,
    '--skip-build': Boolean,
    '--skip-size-check': Boolean,
    '--subdomain': String,
    '--template': String,
    '--version': Boolean,
    '--workspace': String,
    '--yes': Boolean,
    // Aliases
    '--environment': '--env',
    '-e': '--env',
    '-f': '--force',
    '-h': '--help',
    '-n': '--name',
    '-t': '--template',
    '-v': '--version',
    '-y': '--yes'
};
/**
 * Entrypoint for bin/cli.js
 */ export async function main() {
    try {
        await new Main().init();
    } catch (e) {
        if (e instanceof Error) {
            // eslint-disable-next-line no-console
            console.error(e.message);
        }
    }
}
class Main {
    args;
    constructor(){
        // @ts-expect-error bad typings
        this.args = arg(cliArgSpec, {
            permissive: true
        });
        // Set debug flag globally
        if (this.args['--debug']) {
            process.env.DEBUG = 'true';
        }
        // Handle --infra-env flag for infrastructure environment switching
        if (this.args['--infra-env']) {
            const infraEnvArg = this.args['--infra-env'].toLowerCase();
            if (infraEnvArg === 'prod' || infraEnvArg === 'production') {
                setInfraEnvironment('production');
            } else if (infraEnvArg === 'staging') {
                setInfraEnvironment('staging');
            } else if (infraEnvArg === 'devbox') {
                setInfraEnvironment('devbox');
            } else {
                // eslint-disable-next-line no-console
                console.error(`Invalid --infra-env value: ${this.args['--infra-env']}. Use 'production', 'staging', or 'devbox'.`);
                process.exit(1);
            }
        }
    }
    async init() {
        try {
            if (this.args['--help']) {
                helpMessage();
                process.exit(0);
            }
            if (this.args['--version']) {
                const { getOwnVersion } = await import('./utils/version-check.js');
                const version = await getOwnVersion();
                // eslint-disable-next-line no-console
                console.log(version);
                process.exit(0);
            }
            // Get the subcommand (first non-flag argument)
            const subcommand = this.args._[0];
            if (!subcommand) {
                helpMessage();
                process.exit(0);
            }
            // JSON and debug commands output plain text — skip styled intro.
            if (subcommand === 'login' && this.args['--json']) {
                await loginCommand({
                    callbackUrl: this.args['--callback-url'],
                    completeSessionId: this.args['--complete'],
                    headless: this.args['--headless'],
                    json: true
                });
                process.exit(0);
            }
            if (subcommand === 'debug') {
                await debugCommand();
                process.exit(0);
            }
            // dump-tokens outputs plain text
            if (subcommand === 'dump-tokens') {
                await dumpTokensCommand();
                process.exit(0);
            }
            // eslint-disable-next-line no-console
            console.log('\n');
            p.intro(pc.bgCyan(pc.black(' @payloadcms/figma ')));
            // Route to appropriate command handler
            switch(subcommand){
                case 'bootstrap':
                    await bootstrapCommand({
                        id: this.args['--id'],
                        env: this.args['--env'],
                        json: this.args['--json']
                    });
                    break;
                case 'build-lambda-zip':
                    await buildLambdaZipCommand();
                    break;
                case 'deploy':
                    await deployCommand({
                        id: this.args['--id'],
                        name: this.args['--name'],
                        adapter: this.args['--adapter'],
                        debug: this.args['--debug'],
                        description: this.args['--description'],
                        env: this.args['--env'],
                        output: this.args['--output'],
                        region: this.args['--region'],
                        skipBuild: this.args['--skip-build'],
                        skipSizeCheck: this.args['--skip-size-check'],
                        subdomain: this.args['--subdomain'],
                        workspace: this.args['--workspace'],
                        yes: this.args['--yes']
                    });
                    break;
                case 'env':
                    await envCommand({
                        name: this.args._[1]
                    });
                    break;
                case 'init':
                    await initCommand({
                        id: this.args['--id'],
                        name: this.args['--name'],
                        debug: this.args['--debug'],
                        env: this.args['--env'],
                        force: this.args['--force'],
                        noAgent: this.args['--no-agent'],
                        payloadVersion: this.args['--payload-version'],
                        skipAuth: this.args['--skip-auth'],
                        template: this.args['--template']
                    });
                    break;
                case 'list-tokens':
                    listTokensCommand({
                        all: this.args['--all'],
                        debug: this.args['--debug']
                    });
                    break;
                case 'login':
                    await loginCommand({
                        callbackUrl: this.args['--callback-url'],
                        completeSessionId: this.args['--complete'],
                        headless: this.args['--headless']
                    });
                    break;
                case 'logout':
                    await logoutCommand({
                        all: this.args['--all'],
                        debug: this.args['--debug']
                    });
                    break;
                case 'setup-agent':
                    await setupAgentCommand({
                        global: this.args['--global'],
                        project: this.args['--project'],
                        yes: this.args['--yes']
                    });
                    break;
                case 'upgrade':
                    await upgradeCommand({
                        isDryRun: this.args['--dry-run']
                    });
                    break;
                case 'upload-schema':
                    await uploadSchemaCommand({
                        id: this.args['--id'],
                        env: this.args['--env']
                    });
                    break;
                default:
                    p.log.error(pc.red(`Unknown command: ${subcommand}`));
                    p.note('Use --help to see available commands', 'Tip');
                    process.exit(1);
            }
            process.exit(0);
        } catch (err) {
            // eslint-disable-next-line no-console
            console.error(err instanceof Error ? err.message : 'An error occurred');
            process.exit(1);
        }
    }
}
